import json,sys
d=json.load(open(sys.argv[1]))
def find(o,path=''):
  if isinstance(o,dict):
    for k,v in o.items():
      if isinstance(v,(dict,list)): find(v,path+'/'+k)
      elif isinstance(v,str) and v in ('DR-102','DR-111','DR-122','DR-123','DR-125'):
        print('ROW',path, k, v); print(json.dumps(o,ensure_ascii=False)[:3000]); print()
  elif isinstance(o,list):
    for i,v in enumerate(o): find(v,path+f'[{i}]')
find(d)
E
}

